def extostr(e, max_level=30, max_path_level=5):
    if not isinstance(e, Exception):
        raise ValueError("Input must be an Exception instance")

    if not isinstance(max_level, int) or max_level <= 0:
        max_level = 30

    if not isinstance(max_path_level, int) or max_path_level <= 0:
        max_path_level = 5

    stack_up_to = max_level  # we don't ever know the bottom of the stack, so guess 10 levels
    current_index = 0

    try:
        while current_index >= 0:
            frame = e.__traceback__[-current_index - 1]
            line = frame.filename + ':' + str(frame.lineno)

            if line.startswith('__bootstrap__'):
                break

            if frame.f_locals.get('self') is not None:
                line += ' (self ' + str(frame.f_locals['self']) + ')'

            if frame.f_locals.get('klass') is not None:
                line += ' (klass ' + str(frame.f_locals['klass']) + ')'

            path_level = current_index // max_path_level
            message = line
            if path_level > 0:
                message += ' (path level ' + str(path_level) + ')'

            print(message)
            current_index += 1

        # format the exception
        return str(e)
    except IndexError:
        print(f"Error: max_level is too low to inspect traceback")
        return str(e)
    except Exception as e:
        print(f"Error: {e}")
        return str(e)

