def _legacy_mergeOrderings(orderings):
    def _ supportingObj(uniqObj):
        if uniqObj not in orderings: 
            orderings[uniqObj] = []
        return orderings[uniqObj]

    def _orderObj(array):
        return [orderObj[0] for orderObj in array]

    uniqueObj = []
    for ordering in filter(None, orderings): 
        for item in ordering: uniqueObj.append(item)

    uniqueObjNoDup = [i for i, j in zip(uniqueObj,uniqueObj[1:]) if i != j]

    currentIndex = 0
    for uniqObj in uniqueObjNoDup: 
        _supportingObj(uniqObj).append(orderings [currentIndex])
        currentIndex += 1

    allOrderingsList = []
    for uniqueObj in sort(uniqueObjNoDup): 
        allOrderingsList += _orderObj(_supportingObj(uniqueObj))

    return allOrderingsList

