    """
    Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    from krake.data.kubernetes import load_manifests
    manifest_dicts = load_manifests(app.config['spec']['manifest'])

    for manifest in manifest_dicts:
        if 'observer_schema' not in manifest.get('kubernetes', {}):
            # Generate default observer schema for the resource
            default_schema = {
                "type": "object",
                "properties": {
                    "field1": {"type": "string"},
                    "field2": {"type": "integer", "format": "int32"}
                },
                "required": ["field1"]
            }
            manifest['kubernetes']['observer_schema'] = default_schema

