    if dt.fold in (0, 1):
        # Fold state is not ambiguous and we can just convert directly.
        return dt.replace(tzinfo=self.tzinfo)
    else:
        # Find the start and end of the ambiguous time range.
        start, end = ambiguous_range(dt, self.tzinfo)
        if dt in start:
            # If the dt is the start of the ambiguous range, we need to rotate.
            return end.replace(tzinfo=self.tzinfo)
