def parse_diaspora_webfinger(document: str) -> Dict:
    # Decode the URL-encoded document
    decoded_document = urllib.parse.unquote(document)

    # Check if the document is already a dictionary
    if isinstance(decoded_document, dict):
        return decoded_document

    # Check if the document is JSON
    try:
        data = json.loads(decoded_document)
        return data
    except json.JSONDecodeError:
        pass

    # Check if the document is XML
    try:
        # Attempt to parse the document as XML
        from lxml import etree
        root = etree.fromstring(decoded_document.encode())
        return {'name': root.findtext('{http://diaspora.github.io/diaspora_federation/discovery}name')}
    except etree.XMLSyntaxError:
        pass

    # If none of the above formats match, return an empty dictionary
    return {}

